-- CarPaintFinder: provenance-first relational schema (PostgreSQL 15+)
CREATE TABLE manufacturers (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL);
CREATE TABLE vehicle_models (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, manufacturer_id BIGINT NOT NULL REFERENCES manufacturers(id), slug TEXT NOT NULL, name TEXT NOT NULL, UNIQUE(manufacturer_id,slug));
CREATE TABLE sources (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, url TEXT NOT NULL UNIQUE CHECK (url ~ '^https?://'), publisher TEXT NOT NULL, document_title TEXT NOT NULL, license_notes TEXT NOT NULL DEFAULT 'Not assessed', retrieved_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE paint_colors (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, manufacturer_id BIGINT NOT NULL REFERENCES manufacturers(id), oem_code TEXT NOT NULL, name TEXT NOT NULL, finish TEXT, source_id BIGINT NOT NULL REFERENCES sources(id), verification TEXT NOT NULL DEFAULT 'pending' CHECK(verification IN ('pending','verified','rejected')), verified_at TIMESTAMPTZ, UNIQUE(manufacturer_id,oem_code,name), CHECK ((verification <> 'verified') OR verified_at IS NOT NULL));
CREATE TABLE paint_applications (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, paint_color_id BIGINT NOT NULL REFERENCES paint_colors(id) ON DELETE CASCADE, vehicle_model_id BIGINT NOT NULL REFERENCES vehicle_models(id), year_from INT NOT NULL CHECK(year_from BETWEEN 1900 AND 2100), year_to INT NOT NULL CHECK(year_to BETWEEN 1900 AND 2100), source_id BIGINT NOT NULL REFERENCES sources(id), verification TEXT NOT NULL DEFAULT 'pending' CHECK(verification IN ('pending','verified','rejected')), CHECK(year_to>=year_from), UNIQUE(paint_color_id,vehicle_model_id,year_from,year_to));
CREATE TABLE label_locations (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, vehicle_model_id BIGINT NOT NULL REFERENCES vehicle_models(id), year_from INT NOT NULL, year_to INT NOT NULL, location_text TEXT NOT NULL, code_field_hint TEXT, source_id BIGINT NOT NULL REFERENCES sources(id), verification TEXT NOT NULL DEFAULT 'pending' CHECK(verification IN ('pending','verified','rejected')), CHECK(year_to>=year_from), UNIQUE(vehicle_model_id,year_from,year_to,location_text));
CREATE INDEX idx_paint_colors_code ON paint_colors (lower(oem_code));
CREATE INDEX idx_paint_applications_model_year ON paint_applications(vehicle_model_id,year_from,year_to);
-- Only verified records should be exposed on public lookup pages.
CREATE VIEW public_paint_applications AS SELECT pc.id AS paint_color_id, m.name AS manufacturer, vm.name AS model, pc.oem_code, pc.name AS color_name, pa.year_from, pa.year_to FROM paint_applications pa JOIN paint_colors pc ON pc.id=pa.paint_color_id JOIN vehicle_models vm ON vm.id=pa.vehicle_model_id JOIN manufacturers m ON m.id=vm.manufacturer_id WHERE pc.verification='verified' AND pa.verification='verified';

-- Verified label locations only; source URL provides traceability.
CREATE VIEW public_label_locations AS SELECT m.name AS manufacturer,vm.name AS model,ll.year_from,ll.year_to,ll.location_text,ll.code_field_hint,s.url AS source_url FROM label_locations ll JOIN vehicle_models vm ON vm.id=ll.vehicle_model_id JOIN manufacturers m ON m.id=vm.manufacturer_id JOIN sources s ON s.id=ll.source_id WHERE ll.verification='verified';
